void cancelOrderTransactional(Connection c, long orderId) throws SQLException {
  c.setAutoCommit(false);
  try {
    int qty = findQuantityForOrder(c, orderId);
    long productId = findProductIdForOrder(c, orderId);
    deleteOrderItems(c, orderId);
    deleteOrder(c, orderId);
    restoreStock(c, productId, qty);
    c.commit();
  } catch (SQLException e) { c.rollback(); } finally { c.setAutoCommit(true); }
}

